import tm9281523734p from "@/data/manuals/tm-9-2815-237-34p-plates.json";
import type { Diagram } from "./procedures";

/**
 * Interactive plates of the parts manuals: each illustration plate traced to SVG with its
 * callouts, shown on the work package page beside the parts list. Generated by
 * scripts/build_plates.py into data/manuals/<tm>-plates.json; do not hand-edit.
 */
export type Plate = Diagram & {
  /** Review notes, such as key items the plate names only in a bracket. */
  notes: string[];
};

type Generated = { manual: string; plates: Plate[] };
const all: Generated[] = [tm9281523734p as unknown as Generated];

/** The traced plate for a figure, if it has one. */
export const plateFor = (figure: string) => all.flatMap((g) => g.plates).find((p) => p.figure === figure);
/** Every plate SVG, once (served by app/diagrams/[file]/route.ts). */
export const plateFiles = () => all.flatMap((g) => g.plates.map((p) => p.file));
